(() => {
    'use strict';

    const SCRIPT_WIN = window;
    const WIN = window.parent || window;
    const DOC = WIN.document;
    const HOST_JQ = WIN.jQuery || $;

    const NS = 'theme-bg-binder';
    const MENU_ITEM_ID = NS + '-bg-panel-btn';

    let lastTheme = null;
    let cleaned = false;
    let observer = null;
    let nativeAbort = null;

    let applySequence = 0;
    let themeCheckSequence = 0;
    let bgModulePromise = null;
    const previous = WIN[NS];
    if (previous && typeof previous.cleanup === 'function') previous.cleanup();
    const instance = { cleanup };
    WIN[NS] = instance;
    const initialTheme = triggerSlash('/theme');
    initialTheme.then(theme => { if (!cleaned && lastTheme === null) lastTheme = theme; }).catch(console.warn);

    // 在酒馆主窗口加载，复用原生模块与背景缓存。
    function getBgModule() {
        if (!bgModulePromise) {
            bgModulePromise = Promise.resolve().then(() =>
                WIN.Function('url', 'return import(url)')(
                    new WIN.URL('/scripts/backgrounds.js', WIN.location.href).href
                )
            ).catch(() => null);
        }
        return bgModulePromise;
    }

    function currentBgMatches(filename) {
        const bg = DOC.getElementById('bg1');
        const css = bg && (bg.style.backgroundImage || WIN.getComputedStyle(bg).backgroundImage);
        const match = css && css.match(/url\(["']?(.*?)["']?\)/);
        return Boolean(match && getFilename(match[1]) === getFilename(filename));
    }

    async function waitForBackground(filename, sequence) {
        for (let i = 0; i < 20; i++) {
            if (cleaned || sequence !== applySequence) return false;
            if (currentBgMatches(filename)) return true;
            await new Promise(resolve => setTimeout(resolve, 100));
        }
        return false;
    }

    function getFilename(path) {
        if (!path) return '';
        let value = String(path).trim().replace(/^["']|["']$/g, '');
        try {
            const url = new WIN.URL(value, WIN.location.href);
            if (/\/thumbnail$/.test(url.pathname) && url.searchParams.has('file')) {
                return url.searchParams.get('file');
            }
        } catch {}
        value = value.split('?')[0].split('#')[0].split('/').pop().split(String.fromCharCode(92)).pop();
        try { value = decodeURIComponent(value); } catch {}
        return value.trim();
    }

    // 辅助检查：在全局背景面板中查找对应的背景 DOM 元素
    function findGlobalBgElement(filename) {
        const bgMenu = DOC.getElementById('bg_menu_content');
        if (!bgMenu) return null;
        const blocks = bgMenu.querySelectorAll('.bg_example');
        for (const block of blocks) {
            const attrFile = block.getAttribute('bgfile');
            if (block.getAttribute('custom') !== 'true' && attrFile && (attrFile === filename || getFilename(attrFile) === filename)) {
                return block;
            }
            const titleEl = block.querySelector('.BGSampleTitle');
            if (block.getAttribute('custom') !== 'true' && titleEl && titleEl.textContent.trim() === filename) {
                return block;
            }
        }
        return null;
    }

    // 核心修复：自动抢救旧版本数据并迁移到全局变量
    function autoMigrateData() {
        const globalVars = getVariables({ type: 'global' });
        if (!globalVars.squirrel_theme_bg_bindings) {
            let oldBindings = null;
            const oldIds = ['theme-bg-binder-v16', 'theme-bg-binder-v15', 'theme-bg-binder-v14', 'theme-bg-binder-v13', 'theme-bg-binder-v12', 'theme-bg-binder-v11', 'theme-bg-binder-v10', 'theme-bg-binder-v9'];
            for (let oldId of oldIds) {
                try {
                    const oldVars = getVariables({ type: 'script', script_id: oldId });
                    if (oldVars && oldVars.theme_bg_bindings && Object.keys(oldVars.theme_bg_bindings).length > 0) {
                        oldBindings = oldVars.theme_bg_bindings;
                        break;
                    }
                } catch (e) {}
            }
            if (oldBindings) {
                updateVariablesWith(v => {
                    v.squirrel_theme_bg_bindings = oldBindings;
                    return v;
                }, { type: 'global' });
                WIN.toastr.success('已成功继承旧版本的主题壁纸绑定数据！');
            }
        }
    }

    async function checkAndApplyWallpaper() {
        const check = ++themeCheckSequence;
        try {
            await initialTheme.catch(() => {});
            if (cleaned) return;
            const currentTheme = await triggerSlash('/theme');
            if (cleaned || check !== themeCheckSequence || !currentTheme || currentTheme === lastTheme) return;
            lastTheme = currentTheme;
            const sequence = ++applySequence;
            const bindings = getVariables({ type: 'global' }).squirrel_theme_bg_bindings || {};
            const stored = bindings[currentTheme];
            if (!stored) return;
            const names = [...new Set(stored.split('|').map(getFilename).filter(Boolean))];
            if (!names.length) return;
            const mod = await getBgModule();
            if (cleaned || sequence !== applySequence) return;
            let entries = [];
            if (typeof mod?.getSystemBackgroundEntries === 'function') {
                entries = mod.getSystemBackgroundEntries();
                if (!names.some(name => entries.some(e => (e.filename || e) === name)) &&
                    typeof mod.refreshSystemBackgroundEntries === 'function') {
                    entries = await mod.refreshSystemBackgroundEntries();
                }
            }
            if (cleaned || sequence !== applySequence) return;
            const pool = names.filter(name => entries.some(e => (e.filename || e) === name) || findGlobalBgElement(name));
            if (!pool.length) {
                WIN.toastr.warning('未找到已绑定的壁纸。请打开原生背景面板，进入这张图所在的文件夹后重试；必要时清空绑定并重新追加。');
                return;
            }
            const selected = pool[Math.floor(Math.random() * pool.length)];
            if (currentBgMatches(selected)) return;
            if (typeof mod?.applyGlobalBackground === 'function' && entries.some(e => (e.filename || e) === selected)) {
                await mod.applyGlobalBackground(selected);
            } else {
                const block = findGlobalBgElement(selected);
                if (!block) throw new Error('背景面板尚未加载对应图片');
                // 使用主窗口 jQuery，保持原生委托点击的事件与数据环境一致。
                if (WIN.jQuery) WIN.jQuery(block).trigger('click');
                else block.click();
            }
            if (cleaned || sequence !== applySequence) return;
            const applied = await waitForBackground(selected, sequence);
            if (cleaned || sequence !== applySequence) return;
            if (applied) {
                WIN.toastr.success(names.length > 1 ? '已为 ' + escapeHtml(currentTheme) + ' 随机切换壁纸：' + selected : '已切换为 ' + escapeHtml(currentTheme) + ' 的配套壁纸');
            } else {
                WIN.toastr.warning('未确认壁纸已显示。请检查当前聊天是否锁定背景，或重新追加当前壁纸。');
            }
        } catch (error) {
            if (!cleaned) {
                console.warn('[主题壁纸绑定]', error);
                WIN.toastr.warning('壁纸切换未完成，请打开原生背景面板后重试。');
            }
        }
    }

    const PANEL_STYLE = "/* 控件外观交给主题：这里只规定排版、滚动和选图反馈。 */\n.theme-bg-binder-panel { display: flex; flex-direction: column; gap: 12px; min-width: 0; }\n.theme-bg-binder-panel h3 { margin-block: 0 4px; }\n.theme-bg-binder-panel .inline-drawer-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; }\n.theme-bg-binder-panel .inline-drawer-content { padding-top: 10px; }\n.theme-bg-binder-panel .theme-row, .theme-bg-binder-panel .tbb-batch-tools,\n.theme-bg-binder-panel .tbb-theme-fields { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; min-width: 0; }\n.theme-bg-binder-panel .theme-row > label { display: flex; align-items: center; gap: 8px; flex: 1 1 120px; min-width: 0; }\n.theme-bg-binder-panel .theme-row > label span { overflow-wrap: anywhere; }\n.theme-bg-binder-panel .tbb-theme-fields { flex: 2 1 230px; }\n.theme-bg-binder-panel .theme-bg-input { flex: 1 1 100%; width: 100%; min-width: 0; box-sizing: border-box; resize: vertical; }\n.theme-bg-binder-panel .tbb-batch-tools { margin-bottom: 10px; }\n.theme-bg-binder-panel #theme-search-box { width: 100%; box-sizing: border-box; margin-bottom: 10px; }\n.theme-bg-binder-panel #theme-list-container { display: flex; flex-direction: column; gap: 16px; max-height: 40vh; overflow-y: auto; overflow-x: hidden; touch-action: pan-y; -webkit-overflow-scrolling: touch; }\n.theme-bg-native-viewport {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100vw;\n    height: 100vh;\n    height: 100dvh;\n    margin: 0;\n    padding: 0;\n    z-index: 10000;\n    pointer-events: none;\n}\n.theme-bg-native-picker {\n    position: absolute;\n    pointer-events: auto;\n    left: 12px;\n    right: 12px;\n    bottom: max(12px, env(safe-area-inset-bottom, 0px));\n    max-width: 560px;\n    margin-inline: auto;\n    padding: 8px;\n    box-sizing: border-box;\n    background: var(--SmartThemeBlurTintColor);\n    color: var(--SmartThemeBodyColor);\n}\n.theme-bg-native-picker .inline-drawer-header { display: flex; align-items: center; gap: 8px; }\n.theme-bg-native-picker .inline-drawer-content { padding-top: 8px; }\n.tbb-native-heading { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n.tbb-native-count { white-space: nowrap; }\n.tbb-native-tools { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px; }\n#Backgrounds.tbb-native-mode #bg_tabs { padding-bottom: calc(155px + env(safe-area-inset-bottom, 0px)); }\n#Backgrounds.tbb-native-mode :is(#bg_selection_mode_button, #bg_group_add_to_folder_button, #bg_folder_remove_selected_button, #theme-bg-binder-bg-panel-btn, #bg_add_folder_button, #add_background_button_top, #auto_background, .jg-menu, .mobile-only-menu-toggle, .bg_new_folder_tile) { display: none !important; }\n#Backgrounds.tbb-native-mode .bg_tab_button:has(a[href=\"#bg_chat_tab\"]) { display: none !important; }\n#Backgrounds.tbb-native-mode #bg_menu_content .bg_example { outline: none !important; box-shadow: none !important; }\n#Backgrounds.tbb-native-mode #bg_menu_content .bg_example::before {\n    content: '' !important;\n    position: absolute;\n    top: 7px;\n    left: 7px;\n    right: auto;\n    bottom: auto;\n    z-index: 5;\n    display: grid;\n    place-items: center;\n    width: 26px;\n    height: 26px;\n    border-radius: 7px;\n    background: var(--SmartThemeBlurTintColor);\n    color: var(--SmartThemeBodyColor) !important;\n    font-family: sans-serif;\n    font-size: 20px;\n    font-weight: 700;\n    filter: none;\n    pointer-events: none;\n}\n#Backgrounds.tbb-native-mode #bg_menu_content .bg_example::after { content: none !important; }\n#Backgrounds.tbb-native-mode #bg_menu_content .bg_example.tbb-native-selected { box-shadow: inset 0 0 0 3px var(--SmartThemeQuoteColor) !important; }\n#Backgrounds.tbb-native-mode #bg_menu_content .bg_example.tbb-native-selected::before { content: '✓' !important; }\n#Backgrounds.tbb-native-mode #bg_menu_content .bg_example.tbb-native-bound::after {\n    content: '已绑定' !important;\n    position: absolute;\n    right: 6px;\n    bottom: 6px;\n    z-index: 5;\n    padding: 3px 6px;\n    border-radius: 6px;\n    background: var(--SmartThemeBlurTintColor);\n    color: var(--SmartThemeBodyColor);\n    font: 12px sans-serif;\n    filter: none;\n    pointer-events: none;\n}\n\n/* 按钮保持单行，窄屏由容器把整颗按钮换到下一行。 */\n.theme-bg-binder-dialog .popup-controls { flex-wrap: wrap; }\n.theme-bg-binder-panel .menu_button,\n.theme-bg-native-picker .menu_button,\n.theme-bg-binder-dialog .popup-controls .menu_button {\n    white-space: nowrap !important;\n    word-break: normal !important;\n    overflow-wrap: normal !important;\n    flex-shrink: 0;\n}\n";

    const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

    function chooseNativeWallpapers(themeName, currentValue) {
        const host = DOC.getElementById('Backgrounds');
        const gallery = DOC.getElementById('bg_menu_content');
        if (!host?.isConnected || !gallery?.isConnected) {
            throw new Error('请先打开原生背景面板，再使用看图多选。');
        }
        // 仅切换原生图库标签；不进入原生“移动文件”多选模式。
        const globalTab = host.querySelector('a[href="#bg_global_tab"]');
        if (globalTab) globalTab.click();
        const bound = new Set(String(currentValue || '').split('|').map(getFilename).filter(Boolean));
        const selected = new Set();
        const controller = new WIN.AbortController();
        nativeAbort = controller;
        const attributes = new Map();
        // ST 窄屏的 html transform + fixed body 会让根节点高度为 0。
        // 用显式视口高度的定位容器承载浮条，不再依赖根节点的 bottom 参照。
        const viewport = DOC.createElement('div');
        viewport.className = 'theme-bg-native-viewport';
        const bar = DOC.createElement('div');
        bar.className = 'inline-drawer theme-bg-native-picker';
        bar.setAttribute('role', 'region');
        bar.setAttribute('aria-label', '为主题选择壁纸');
        const style = DOC.createElement('style');
        style.textContent = PANEL_STYLE;
        const heading = DOC.createElement('strong');
        heading.className = 'tbb-native-heading';
        heading.textContent = '选图 → ' + themeName;
        heading.title = themeName;
        const count = DOC.createElement('span');
        count.className = 'tbb-native-count';
        count.setAttribute('aria-live', 'polite');
        const tools = DOC.createElement('div');
        tools.className = 'tbb-native-tools';
        const header = DOC.createElement('div');
        header.className = 'inline-drawer-toggle inline-drawer-header';
        const icon = DOC.createElement('div');
        icon.className = 'inline-drawer-icon fa-solid fa-circle-chevron-up up interactable';
        icon.setAttribute('role', 'button');
        icon.tabIndex = 0;
        const content = DOC.createElement('div');
        content.className = 'inline-drawer-content';
        content.style.display = 'block';
        const hint = DOC.createElement('small');
        hint.textContent = '点图片勾选，可跨文件夹选择';
        header.append(heading, count, icon);
        content.append(hint, tools);
        bar.append(style, header, content);
        host.classList.add('tbb-native-mode');
        viewport.append(bar);
        DOC.body.append(viewport);

        return new Promise(resolve => {
            let settled = false;
            const action = (text, className, handler) => {
                const button = DOC.createElement('button');
                button.type = 'button';
                button.className = 'menu_button interactable ' + className;
                button.textContent = text;
                button.addEventListener('click', handler, { signal: controller.signal });
                tools.append(button);
                return button;
            };
            const confirm = action('返回并追加', 'tbb-native-confirm', () => finish([...selected]));
            action('清空本次', 'tbb-native-clear', () => { selected.clear(); sync(); });
            action('取消选图', 'tbb-native-cancel', () => finish(null));

            function sync() {
                const blocks = host.querySelectorAll('#bg_menu_content .bg_example');
                for (const block of blocks) {
                    if (block.getAttribute('custom') === 'true') continue;
                    const file = block.getAttribute('bgfile');
                    if (!file) continue;
                    if (!attributes.has(block)) {
                        attributes.set(block, Object.fromEntries(['role', 'aria-checked', 'aria-disabled']
                            .map(key => [key, block.getAttribute(key)])));
                    }
                    const alreadyBound = bound.has(file);
                    const checked = alreadyBound || selected.has(file);
                    block.classList.toggle('tbb-native-selected', checked);
                    block.classList.toggle('tbb-native-bound', alreadyBound);
                    block.setAttribute('role', 'checkbox');
                    block.setAttribute('aria-checked', String(checked));
                    block.setAttribute('aria-disabled', String(alreadyBound));
                }
                count.textContent = '新选 ' + selected.size + ' 张';
                confirm.textContent = '返回并追加（' + selected.size + '）';
            }
            function toggle(block) {
                const file = block.getAttribute('bgfile');
                if (!file || bound.has(file)) return;
                if (selected.has(file)) selected.delete(file);
                else selected.add(file);
                sync();
            }
            function stop(event) {
                event.preventDefault();
                event.stopImmediatePropagation();
            }
            function handleClick(event) {
                if (!(event.target instanceof WIN.Element)) return;
                const target = event.target;
                if (!host.contains(target)) return;
                // 图库的文件夹跳转、排序、筛选和缩放仍交给原生处理。
                // 图片点击只勾选；拦住相关编辑操作，避免点图时改背景或改文件。
                if (target.closest('#theme-bg-binder-bg-panel-btn, #bg_selection_mode_button, #bg_group_add_to_folder_button, #bg_folder_remove_selected_button, #bg_add_folder_button, #add_background_button_top, #auto_background, .jg-button, .mobile-only-menu-toggle, a[href="#bg_chat_tab"]')) {
                    stop(event);
                    return;
                }
                const block = target.closest('.bg_example');
                if (block) {
                    stop(event);
                    if (block.closest('#bg_menu_content') && block.getAttribute('custom') !== 'true') toggle(block);
                }
            }
            function handleKey(event) {
                if (event.key === 'Escape' && !DOC.querySelector('dialog[open]')) {
                    stop(event);
                    finish(null);
                    return;
                }
                if ((event.key === ' ' || event.key === 'Enter') && event.target instanceof WIN.Element) {
                    const block = event.target.closest('#bg_menu_content .bg_example');
                    if (block && host.contains(block)) {
                        stop(event);
                        if (!event.repeat) toggle(block);
                    }
                }
            }
            function handleContext(event) {
                if (event.target instanceof WIN.Element && host.contains(event.target) && event.target.closest('.bg_example, .bg_folder_tile')) stop(event);
            }
            function finish(result) {
                if (settled) return;
                settled = true;
                observer.disconnect();
                controller.abort();
                host.classList.remove('tbb-native-mode');
                for (const [block, previous] of attributes) {
                    block.classList.remove('tbb-native-selected', 'tbb-native-bound');
                    for (const [key, value] of Object.entries(previous)) {
                        if (value === null) block.removeAttribute(key);
                        else block.setAttribute(key, value);
                    }
                }
                attributes.clear();
                viewport.remove();
                if (nativeAbort === controller) nativeAbort = null;
                resolve(result);
            }
            // 只在本次选图期间观察原生图库重建，结束时一起释放。
            const observer = new WIN.MutationObserver(sync);
            observer.observe(host, { childList: true, subtree: true });
            controller.signal.addEventListener('abort', () => finish(null), { once: true });
            DOC.addEventListener('click', handleClick, { capture: true, signal: controller.signal });
            DOC.addEventListener('keydown', handleKey, { capture: true, signal: controller.signal });
            DOC.addEventListener('contextmenu', handleContext, { capture: true, signal: controller.signal });
            sync();
        });
    }


    function readThemeNames() {
        // TT 的 Panel Runtime 可将关闭的设置面板移出 document。
        // /theme 的原生补全枚举直接来自内存中的 themes，面板关闭时也可读取。
        // 已核对 TT v2.2.0 与 v2.4.0 的命令注册及 getContext 导出。
        const context = WIN.SillyTavern?.getContext?.() || SillyTavern;
        const argument = context.SlashCommandParser?.commands?.theme?.unnamedArgumentList?.[0];
        let values;
        if (typeof argument?.enumProvider === 'function') {
            const entries = argument.enumProvider();
            if (!Array.isArray(entries)) throw new Error('/theme 补全列表不是数组');
            values = entries.map(entry => entry.value);
        } else {
            // 没有暴露命令枚举的环境，沿用原生主题控件读取方式。
            const select = DOC.getElementById('themes');
            values = Array.from(select?.options || [], option => option.value);
        }
        return [...new Set(values.filter(value => typeof value === 'string' && value.trim() !== ''))];
    }

    async function waitForThemeNames() {
        // 面板刚初始化或主题导入时，选项可能尚未填充；每次重新定位控件。
        for (let attempt = 0; attempt <= 10; attempt++) {
            if (cleaned) return [];
            const names = readThemeNames();
            if (names.length || attempt === 10) return names;
            await new Promise(resolve => WIN.setTimeout(resolve, 100));
        }
    }

    async function openPanel(state = null) {
        if (cleaned) return;
        const currentTheme = await triggerSlash('/theme') || "未知主题";
        let themes = [];
        try {
            themes = await waitForThemeNames();
        } catch (error) {
            console.error('[主题壁纸绑定] 无法读取原生主题数据', error);
        }
        if (cleaned) return;
        if (!themes.length) {
            const select = DOC.getElementById('themes');
            console.warn('[主题壁纸绑定] 主题列表为空', {
                found: Boolean(select),
                tag: select?.tagName,
                optionCount: select?.options?.length ?? null,
                selectedValue: select?.value ?? null,
            });
        }

        const vars = getVariables({ type: 'global' });
        const existingBindings = state?.bindings || vars.squirrel_theme_bg_bindings || {};
        let newBindings = Object.assign({}, existingBindings);
        let nativeRequest = null;

        let html = '<style>' + PANEL_STYLE + '</style><div class="theme-bg-binder-panel">';
        html += '<h3>主题壁纸绑定设置</h3>';

        const currentBg = existingBindings[currentTheme] || "";
        html += '<div class="tbb-current-card inline-drawer">';
        html += '<div class="inline-drawer-toggle inline-drawer-header"><b>当前主题：' + escapeHtml(currentTheme) + '</b><div class="inline-drawer-icon fa-solid fa-circle-chevron-up up interactable" role="button" tabindex="0"></div></div><div class="inline-drawer-content" style="display:block">';
        html += '<div class="theme-row" data-theme="' + escapeHtml(currentTheme) + '">';
        html += '<textarea class="text_pole textarea_compact theme-bg-input" data-theme="' + escapeHtml(currentTheme) + '" placeholder="留空即不绑定，多张自动以 | 分隔" rows="2">' + escapeHtml(currentBg) + '</textarea>';
        html += '<button type="button" class="grab-bg-btn menu_button interactable">追加当前</button>';
        html += '<button type="button" class="unbind-bg-btn menu_button interactable">清空</button>';
        html += '<button type="button" class="pick-bgs-btn menu_button interactable" data-theme="' + escapeHtml(currentTheme) + '">看图多选</button>';
        html += '</div></div></div>';

        if (themes.length === 0) {
            html += '<p>暂时无法读取主题列表，请关闭后重试。当前主题的壁纸绑定仍可在上方设置。</p>';
        } else {
            html += '<div class="inline-drawer tbb-themes-drawer"><div class="inline-drawer-toggle inline-drawer-header"><b>全部主题 (' + themes.length + ')</b><div class="inline-drawer-icon fa-solid fa-circle-chevron-up up interactable" role="button" tabindex="0"></div></div>';
            html += '<div class="inline-drawer-content" style="display:block">';

            html += '<div class="tbb-batch-tools">';
            html += '<label>';
            html += '<input type="checkbox" id="batch-select-all"> 全选';
            html += '</label>';
            html += '<button type="button" id="batch-grab-btn" class="menu_button interactable">✨ 批量添加当前</button>';
            html += '<button type="button" id="batch-unbind-btn" class="menu_button interactable">🗑️ 批量清空</button>';
            html += '</div>';

            html += '<input type="text" class="text_pole" id="theme-search-box" placeholder="🔍 搜索主题名称 (支持实时过滤)...">';
            html += '<div id="theme-list-container">';

            themes.forEach(theme => {
                const bg = existingBindings[theme] || "";
                html += '<div class="theme-row" data-theme="' + escapeHtml(theme) + '">';
                html += '<label>';
                html += '<input type="checkbox" class="theme-checkbox" value="' + escapeHtml(theme) + '">';
                html += '<span>' + escapeHtml(theme) + '</span>';
                html += '</label>';
                html += '<div class="tbb-theme-fields">';
                html += '<textarea class="text_pole textarea_compact theme-bg-input" data-theme="' + escapeHtml(theme) + '" placeholder="未绑定" rows="2">' + escapeHtml(bg) + '</textarea>';
                html += '<button type="button" class="grab-bg-btn menu_button interactable">追加</button>';
                html += '<button type="button" class="unbind-bg-btn menu_button interactable">清空</button>';
                html += '<button type="button" class="pick-bgs-btn menu_button interactable" data-theme="' + escapeHtml(theme) + '">看图多选</button>';
                html += '</div></div>';
            });
            html += '</div></div></div>';
        }
        html += '</div>';

        SillyTavern.callGenericPopup(html, SillyTavern.POPUP_TYPE.TEXT, "", {
            okButton: "💾 保存设置",
            cancelButton: "取消",
            wide: true,
            onOpen: async (popup) => {
                popup.dlg.classList.add('theme-bg-binder-dialog');
                const $dlg = $(popup.dlg);

                $dlg.find('#theme-search-box').on('input', function() {
                    const query = $(this).val().toLowerCase();
                    $dlg.find('#theme-list-container .theme-row').each(function() {
                        $(this).toggle((this.dataset.theme || '').toLowerCase().includes(query));
                    });
                });

                $dlg.find('.theme-bg-input').on('input', function() {
                    const themeName = this.dataset.theme;
                    const selectedBg = $(this).val().trim();
                    $dlg.find('.theme-bg-input').filter(function() { return this.dataset.theme === themeName; }).not(this).val(selectedBg);
                    if (selectedBg) newBindings[themeName] = selectedBg;
                    else delete newBindings[themeName];
                });

                $dlg.find('.unbind-bg-btn').on('click', function(e) {
                    e.preventDefault();
                    $(this).siblings('.theme-bg-input').val('').trigger('input');
                    WIN.toastr.info('壁纸池已清空。');
                });

                const fetchCurrentBg = () => {
                    const selected = DOC.querySelector('#bg_menu_content .bg_example.selected-background');
                    const selectedFile = selected && selected.getAttribute('bgfile');
                    if (selectedFile && currentBgMatches(selectedFile)) return selectedFile;
                    let currentBg = '';
                    const bg1 = DOC.getElementById('bg1');
                    if (bg1 && bg1.style.backgroundImage && bg1.style.backgroundImage !== 'none') {
                        let bgStr = bg1.style.backgroundImage;
                        if (bgStr.indexOf('url(') !== -1) {
                            let start = bgStr.indexOf('url(') + 4;
                            let end = bgStr.lastIndexOf(')');
                            if (end > start) {
                                let inner = bgStr.substring(start, end).trim();
                                if ((inner.startsWith('"') && inner.endsWith('"')) || (inner.startsWith("'") && inner.endsWith("'"))) {
                                    inner = inner.substring(1, inner.length - 1);
                                }
                                try { inner = decodeURIComponent(inner); } catch (err) {}
                                currentBg = getFilename(inner);
                            }
                        }
                    }
                    return currentBg;
                };

                const appendBgToInput = ($input, newBg) => {
                    let currentVal = $input.val().trim();
                    let bgList = currentVal ? currentVal.split('|').map(s => getFilename(s)).filter(Boolean) : [];
                    if (!bgList.includes(newBg)) {
                        bgList.push(newBg);
                        $input.val(bgList.join(' | ')).trigger('input');
                        return true;
                    }
                    return false;
                };

                $dlg.find('.grab-bg-btn').on('click', function(e) {
                    e.preventDefault();
                    const currentBg = fetchCurrentBg();
                    if (currentBg) {
                        const hasLoadedBgs = DOC.querySelectorAll('#bg_menu_content .bg_example').length > 0;
                        if (hasLoadedBgs && !findGlobalBgElement(currentBg)) {
                            WIN.toastr.warning('检测到当前壁纸不在【系统全局背景】中（可能传到了下方自定义聊天背景区），切换时可能无法生效哦！');
                        }
                        const $input = $(this).siblings('.theme-bg-input');
                        if (appendBgToInput($input, currentBg)) {
                            WIN.toastr.success('已追加提取当前壁纸：' + currentBg);
                        } else {
                            WIN.toastr.info('该壁纸已在池中，无需重复添加。');
                        }
                    } else {
                        WIN.toastr.warning('未检测到背景，请确认界面已有背景图。');
                    }
                });

                $dlg.find('.pick-bgs-btn').on('click', async function(e) {
                    e.preventDefault();
                    if (cleaned || nativeRequest) return;
                    if (!DOC.getElementById('bg_menu_content')?.isConnected) {
                        WIN.toastr.warning('请先打开原生背景面板，再使用看图多选。');
                        return;
                    }
                    nativeRequest = {
                        themeName: this.dataset.theme,
                        search: String($dlg.find('#theme-search-box').val() || ''),
                        listScroll: $dlg.find('#theme-list-container').scrollTop() || 0,
                    };
                    $dlg.find('.pick-bgs-btn').prop('disabled', true);
                    // 完整关闭原生弹窗，恢复图库可交互性，同时保留本面板草稿。
                    await popup.completeCancelled();
                });

                $dlg.find('#batch-select-all').on('change', function() {
                    const isChecked = $(this).is(':checked');
                    $dlg.find('#theme-list-container .theme-row:visible .theme-checkbox').prop('checked', isChecked);
                });

                $dlg.find('#batch-grab-btn').on('click', function(e) {
                    e.preventDefault();
                    const checkedBoxes = $dlg.find('.theme-checkbox:checked');
                    if (checkedBoxes.length === 0) {
                        WIN.toastr.warning('请先勾选需要批量操作的主题！');
                        return;
                    }
                    const currentBg = fetchCurrentBg();
                    if (!currentBg) {
                        WIN.toastr.warning('未检测到背景，请确认界面已有背景图。');
                        return;
                    }
                    const hasLoadedBgs = DOC.querySelectorAll('#bg_menu_content .bg_example').length > 0;
                    if (hasLoadedBgs && !findGlobalBgElement(currentBg)) {
                        WIN.toastr.warning('检测到当前壁纸不在【系统全局背景】中，切换时可能无法生效哦！');
                    }
                    let appendCount = 0;
                    checkedBoxes.each(function() {
                        const themeName = $(this).val();
                        const $input = $dlg.find('.theme-bg-input').filter(function() { return this.dataset.theme === themeName; });
                        if (appendBgToInput($input, currentBg)) appendCount++;
                    });
                    if (appendCount > 0) {
                        WIN.toastr.success('已为 ' + appendCount + ' 个主题追加了壁纸！');
                    } else {
                        WIN.toastr.info('所选主题的壁纸池中均已包含此壁纸。');
                    }
                });

                $dlg.find('#batch-unbind-btn').on('click', function(e) {
                    e.preventDefault();
                    const checkedBoxes = $dlg.find('.theme-checkbox:checked');
                    if (checkedBoxes.length === 0) {
                        WIN.toastr.warning('请先勾选需要清空的主题！');
                        return;
                    }
                    checkedBoxes.each(function() {
                        const themeName = $(this).val();
                        $dlg.find('.theme-bg-input').filter(function() { return this.dataset.theme === themeName; }).val('').trigger('input');
                    });
                    WIN.toastr.info('已清空 ' + checkedBoxes.length + ' 个主题的壁纸池。');
                });
                if (state?.search) $dlg.find('#theme-search-box').val(state.search).trigger('input');
                if (state?.listScroll) $dlg.find('#theme-list-container').scrollTop(state.listScroll);
            }
        }).then(async result => {
            if (nativeRequest && !cleaned) {
                try {
                    const name = nativeRequest.themeName;
                    const picked = await chooseNativeWallpapers(name, newBindings[name] || '');
                    if (cleaned) return;
                    if (picked?.length) {
                        const pool = new Set(String(newBindings[name] || '').split('|').map(getFilename).filter(Boolean));
                        let added = 0;
                        for (const filename of picked) if (!pool.has(filename)) { pool.add(filename); added++; }
                        newBindings[name] = [...pool].join(' | ');
                        if (added) WIN.toastr.success('已追加 ' + added + ' 张壁纸，点击“保存设置”后生效。');
                    }
                } catch (error) {
                    console.error('[主题壁纸绑定] 原生图库选图失败', error);
                    WIN.toastr.warning(error.message || '原生图库选图失败，请重新打开背景面板。');
                }
                if (!cleaned) void openPanel({ bindings: newBindings, search: nativeRequest.search, listScroll: nativeRequest.listScroll });
                return;
            }
            if (result === SillyTavern.POPUP_RESULT.AFFIRMATIVE && !cleaned) {
                updateVariablesWith(v => {
                    v.squirrel_theme_bg_bindings = newBindings;
                    return v;
                }, { type: 'global' });
                WIN.toastr.success("主题壁纸绑定已生效！");
            }
        });
    }

    function ensureBgPanelButton() {
        if (cleaned) return;
        const controlsDiv = DOC.querySelector('#bg_tabs .heading-controls');
        if (!controlsDiv) return;

        let item = DOC.getElementById(MENU_ITEM_ID);
        if (!item) {
            item = DOC.createElement('button');
            item.id = MENU_ITEM_ID;
            item.className = 'menu_button menu_button_icon interactable';
            item.title = '🎨 主题壁纸绑定管理器';
            item.setAttribute('role', 'button');
            item.setAttribute('tabindex', '0');

            const icon = DOC.createElement('i');
            icon.className = 'fa-solid fa-images fa-fw';
            item.appendChild(icon);

            item.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                openPanel();
            });
        }

        if (item.parentElement !== controlsDiv) {
            controlsDiv.prepend(item);
        }
    }

    function bindObserver() {
        observer = new WIN.MutationObserver(mutations => {
            if (mutations.some(mutation => mutation.type === 'childList' || mutation.type === 'attributes')) {
                ensureBgPanelButton();
            }
        });
        observer.observe(DOC.body, { childList: true, subtree: true });
    }

    function init() {
        autoMigrateData();

        // 使用主窗口 jQuery，兼容美化管理通过主窗口 .trigger('change') 切换主题。
        HOST_JQ(DOC).on('change.themeBgHelper', '#themes', checkAndApplyWallpaper);
        eventOn(tavern_events.SETTINGS_UPDATED, checkAndApplyWallpaper);

        ensureBgPanelButton();
        bindObserver();

        SCRIPT_WIN.addEventListener('pagehide', cleanup, { once: true });
        SCRIPT_WIN.addEventListener('beforeunload', cleanup, { once: true });
    }

    function cleanup() {
        if (cleaned) return;
        cleaned = true;
        ++applySequence;
        ++themeCheckSequence;
        if (WIN[NS] === instance) delete WIN[NS];
        HOST_JQ(DOC).off('change.themeBgHelper');
        observer?.disconnect();
        observer = null;
        try { nativeAbort?.abort(); } catch {}
        nativeAbort = null;
        DOC.getElementById(MENU_ITEM_ID)?.remove();
    }

    init();
})();
